fun main() {
    println("7".padStart(3, '0'))
    println("ab".padEnd(5, '.') + "|")
    println("%d items".format(5))
    println("%5d|%-5d|%05d".format(42, 42, 42))
    println("%.2f %8.3f %e".format(3.14159, 2.71828, 12345.678))
    println("%s and %S".format("x", "y"))
    println("%x %X %o %b %c".format(255, 255, 8, true, 'q'))
    println("%,d".format(1234567))
    println("%+d %+d".format(5, -5))
    println("%10s|%-10s|".format("r", "l"))
    println("%%")
    println("a-b-c".substringBefore("-") + "a-b-c".substringAfterLast("-"))
    println("  trim me ".trim() + "|" + "xxhixx".trim('x'))
    println("hello".capitalize2())
    println("Hello World".lowercase() + "Hello".uppercase())
    println("abc".reversed() + "abc".repeat(2))
    println("a,b,,c".split(","))
    println("a,b,,c".split(",").filter { it.isNotEmpty() })
    println("hello".indexOf('l') to "hello".lastIndexOf("l"))
    println("hello".substring(1, 3) + "hello".drop(3) + "hello".dropLast(1))
    println("abc" < "abd")
    println("ab".compareTo("abc"))
    println("tEsT".equals("TEST", ignoreCase = true))
    println("line1\nline2\r\nline3".lines())
    println("%08.3f".format(-3.14159))
    println("abc".toCharArray().joinToString("-"))
    println("x=${1 + 2}, y=${"s".length}")
    println("""raw \n $"""+"""text""")
    println("a\tb".length)
    println("é".length)
}

fun String.capitalize2() = replaceFirstChar { it.uppercase() }
